  0 <= c_secret (ctx st) < 2^64 -> c_init_done (ctx st) = 1 ->
  rw_cells psegs m (conc st p) [C8 (wz 0); C8 (wz 0); C4 (wz 0); C4 (wz 0)] ->
  rw_cells psegs m (conc st p + 24) [CB 4072 (zeros 4072)] ->
